#!/usr/bin/env python3
"""Visualize image quality metrics generated by the CUDA auditor."""

import argparse
import csv
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt


def main():
    parser = argparse.ArgumentParser(
        description="Generate a visual dataset quality dashboard."
    )
    parser.add_argument("--quality", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()

    with args.quality.open(newline="", encoding="utf-8") as file:
        rows = list(csv.DictReader(file))

    if not rows:
        parser.error("The quality report is empty")

    metrics = [
        ("mean_brightness", "Brightness", "#4776B4"),
        ("contrast", "Contrast", "#2E9C83"),
        ("blur_score", "Laplacian Variance", "#E49A46"),
    ]

    fig, axes = plt.subplots(1, 3, figsize=(15, 4.5))

    for ax, (column, title, color) in zip(axes, metrics):
        values = [float(row[column]) for row in rows]
        ax.hist(values, bins=15, color=color, edgecolor="white")
        ax.set_title(title, fontsize=13)
        ax.set_xlabel("Metric value")
        ax.set_ylabel("Number of images")
        ax.grid(axis="y", alpha=0.2)

    fig.suptitle(
        f"GPU Visual Dataset Audit — {len(rows)} Images",
        fontsize=16,
        fontweight="bold",
    )
    fig.tight_layout()

    args.output.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(args.output, dpi=180, bbox_inches="tight")
    plt.close(fig)

    print(f"Dashboard generated: {args.output}")


if __name__ == "__main__":
    main()
